function H0_BARCODE(V, filtration sorted by threshold):
    for v in V: parent[v] <- v; birth[v] <- 0
    bars <- []
    for (t, (a,b)) in filtration:
        ra <- FIND(a); rb <- FIND(b)
        if ra != rb:
            young, old <- younger/older of ra, rb by birth
            append (birth[young], t) to bars
            parent[young] <- old
    for r in distinct roots:
        append (birth[r], +inf) to bars
    return bars

